// Program state map for local return-value candidates.
// The mapping: VarDecl* -> bool (true means initialized, false means uninitialized).
REGISTER_MAP_WITH_PROGRAMSTATE(UninitVarMap, const VarDecl*, bool)

namespace {

class SAGenTestChecker : public Checker<check::PostStmt<DeclStmt>,
                                          check::Bind,
                                          check::PreStmt<ReturnStmt>> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker() 
      : BT(new BugType(this, "Uninitialized Variable", "Uninitialized ret usage")) {}

  // Called after a declaration statement is processed.
  void checkPostStmt(const DeclStmt *DS, CheckerContext &C) const;

  // Called when a value is bound to a variable.
  void checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const;

  // Called before a return statement is processed.
  void checkPreStmt(const ReturnStmt *RS, CheckerContext &C) const;
};

// checkPostStmt: Records uninitialized local variables whose value can be
// returned directly from the enclosing scalar-returning function.
void SAGenTestChecker::checkPostStmt(const DeclStmt *DS, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const auto *FD = dyn_cast_or_null<FunctionDecl>(C.getLocationContext()->getDecl());
  if (!FD)
    return;

  for (const Decl *D : DS->decls()) {
    const auto *VD = dyn_cast<VarDecl>(D);
    if (!VD || VD->hasInit() || !VD->isLocalVarDecl())
      continue;

    if (VD->getType()->isScalarType() &&
        C.getASTContext().hasSameType(VD->getType(), FD->getReturnType()))
      State = State->set<UninitVarMap>(VD, false);
  }
  C.addTransition(State);
}

// checkBind: Processes bindings to update the initialization status of a
// tracked local variable.
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const auto *VR = dyn_cast_or_null<VarRegion>(Loc.getAsRegion());
  if (VR) {
    const VarDecl *VD = VR->getDecl();
    if (State->get<UninitVarMap>(VD))
      State = State->set<UninitVarMap>(VD, true);
  }
  C.addTransition(State);
}

// checkPreStmt: Reports a direct return of a tracked uninitialized local.
void SAGenTestChecker::checkPreStmt(const ReturnStmt *RS, CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const Expr *retExpr = RS->getRetValue();
  if (!retExpr)
    return;

  retExpr = retExpr->IgnoreImplicit();
  if (const auto *DRE = dyn_cast<DeclRefExpr>(retExpr)) {
    if (const auto *VD = dyn_cast<VarDecl>(DRE->getDecl())) {
      const bool *Initialized = State->get<UninitVarMap>(VD);
      if (Initialized && !(*Initialized)) {
        ExplodedNode *N = C.generateNonFatalErrorNode();
        if (!N)
          return;
        auto report = std::make_unique<PathSensitiveBugReport>(
            *BT, "Uninitialized local variable returned", N);
        report->addRange(retExpr->getSourceRange());
        C.emitReport(std::move(report));
      }
    }
  }
  C.addTransition(State);
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker", 
      "Detects usage of uninitialized local variable 'ret'", 
      "");
}

